const fs = require("fs");
const path = require("path");
const childProcess = require("child_process");

const PSOLA = require("../../util/psola.js");
const env = require("../../util/env-util.js");
const TempFolder = require('../../util/temp-folder.js');
const FFmpegUtil = require("../../util/ffmpeg-util.js");
const downloadAttachments = require('../../util/download-attachments.js');

const keyFrequency = require("../../resources/key-frequency.json");

class Command {
    constructor() {
        this.name = "pitchcorrect";
        this.description = "Pitch-correct a sample to a key/frequency";
        this.attributes = {
            unlisted: false,
            lockedToCommands: true,
            permission: 0,
        };

        this.example = [
            { text: "{{prefix}}pitchcorrect" },
            { text: "{{prefix}}pitchcorrect c5" },
            { text: "{{prefix}}pitchcorrect d#6" },
            { text: "{{prefix}}pitchcorrect 1479.98" },
        ];
    }

    async handle(message, args, util) {
        // get attachements
        const attachment = message.attachments.first();
        if (!attachment) throw new Error("Add an  audio");
        const endingType = util.getAttachmentType(attachment);
        if (!FFmpegUtil.isCompatibleAudio(endingType)) throw new Error('Please use a valid audio format.');
        // check atachemtn size
        if (attachment.size > 15 * 1e+6) throw new Error("Files must be below 15 MB.");

        // frequency to use
        const inputFrequency = args[0] || keyFrequency.c5;
        const frequency = keyFrequency[inputFrequency] || Number(inputFrequency);
        if (!frequency || isNaN(frequency) || !isFinite(frequency)) throw new Error("Thats not a frequency");
        if (frequency < keyFrequency.c0 || frequency > keyFrequency.eb8) throw new Error("Thats not in the range");

        // actually start doing stuff
        const startTime = Date.now();
        const jobName = TempFolder.makeTempName("pitchcorrect");
        const temporaryFolder = new TempFolder(jobName);
        await temporaryFolder.createAndDestroy(async (tempDir) => {
            // download
            const replyMessage = await message.reply("Downloading contents...");
            const [rawInputPath] = await downloadAttachments([attachment], (i) => `input${i}.bin`, tempDir);
            console.log(rawInputPath);
            // convert to safe type
            await replyMessage.edit("Converting contents...");
            const inputPath = path.join(tempDir, `inputsafe.ogg`);
            await FFmpegUtil.commands.convertToSafeOgg(rawInputPath, inputPath);
            // check length
            const length = await FFmpegUtil.probe.length(inputPath);
            if (length > 10 * 60) return replyMessage.edit("Files must be within 10 minutes long OR you can buy me 64 gigabytes of ram 🎉");

            // do the thing
            await replyMessage.edit(`pitching sample to ${frequency} Hz`);
            const outputPathWav = path.join(tempDir, "output_pitched.wav");
            await PSOLA.pitchCorrect(inputPath, outputPathWav, frequency);

            // convret to ogg
            await replyMessage.edit(`making ogg because Hfat file`);
            const outputPathCorrected = path.join(tempDir, "pitch_corrected.ogg");
            await FFmpegUtil.commands.convertToSafeOgg(outputPathWav, outputPathCorrected);

            await replyMessage.edit({
                content: "Completed in " + ((Date.now() - startTime) / 1000) + " seconds"
                    + "\n" + `-# Generated by <@${message.author.id}>`,
                files: [outputPathCorrected]
            });
        });
    }
    async invoke(message, args, util) {
        await this.handle(message, args, util);
    }
}

// needs to do new Command() in index.js because typing static every time STINKS!
module.exports = Command;